function renderGPUStats(){const mode=gpuReceipt?.mode||gpuViewport.mode||'canvas-fallback',summary=gpuFramePayload?.summary,stats=summary?.stats||{},modeEl=$('#gpuMode');modeEl.textContent=mode==='webgpu'?'WebGPU 实时':'Canvas 参考';modeEl.className=mode==='webgpu'?'webgpu':'fallback';$('#gpuFrame').textContent=summary?`Frame ${String(summary.frame_plan_root||'').slice(0,10)}`:'Frame —';const total=gpuReceipt?((gpuReceipt.uploadMs||0)+(gpuReceipt.encodeMs||0)+(gpuReceipt.submitMs||0)).toFixed(2):'—';$('#gpuPerf').textContent=`${total} ms`;$('#gpuWatch').innerHTML=`<div><span>Backend</span><b>${esc(mode)}</b></div><div><span>Frame Plan</span><b>${esc(String(summary?.frame_plan_root||'—').slice(0,14))}</b></div><div><span>Draw Calls</span><b>${stats.estimatedDrawCalls??'—'}</b></div><div><span>Particles</span><b>${stats.particleSeeds??'—'}</b></div><div><span>Lights</span><b>${stats.lights??'—'}</b></div><div><span>Compile</span><b>${gpuFramePayload?.compile_ms?.toFixed?.(2)??'—'} ms</b></div>`}
function scheduleGPU(force=false){if(gpuRefreshTimer)clearTimeout(gpuRefreshTimer);gpuRefreshTimer=setTimeout(()=>refreshGPU(force),force?0:80)}
async function refreshGPU(force=false){if(!gpuEnabled||activeView!=='scene'){gpuViewport.setEnabled(false);renderGPUStats();return}if(!server){gpuViewport.setEnabled(false);gpuReceipt={mode:'canvas-fallback',reason:'离线模式',submitted:false};renderGPUStats();return}try{gpuFramePayload=await api('/api/unified/session/gpu-frame',{session_id:sessionId,quality:gpuQuality,observer:'player',gpu_tier:2});gpuReceipt=await gpuViewport.render(gpuFramePayload.frame,(inspection?.behavior?.runtime?.tick||0)/20);renderGPUStats()}catch(e){gpuReceipt={mode:'canvas-fallback',reason:e.message,submitted:false};gpuViewport.setEnabled(false);renderGPUStats();if(force)toast(`GPU视口降级：${e.message}`)}}
function renderInspector(){if(leftTab==='ui'){const n=activeUITree()?.nodes.find(n=>n.ui_node_id===selectedUiNodeId);$('#inspectTitle').textContent=n?.name||'UI';$('#inspectSub').textContent=n?.ui_node_id||'—';$('#selectionKind').textContent=n?.type||'ui';$('#inspector').innerHTML=n?`<div class="field"><label>名称</label><input id="uiName" value="${esc(n.name)}"></div><div class="field"><label>文本</label><input id="uiText" value="${esc(n.text||'')}"></div><div class="field-row"><div class="field"><label>左偏移</label><input id="uiLeft" type="number" value="${n.offsets?.left||0}"></div><div class="field"><label>上偏移</label><input id="uiTop" type="number" value="${n.offsets?.top||0}"></div></div><div class="field"><label>数据绑定</label><input value="${esc(JSON.stringify(n.bindings||{}))}" disabled></div><div class="inspect-actions"><button id="applyUI" class="primary">应用</button>${n.ui_node_id!==activeUITree().root_id?'<button id="deleteUI">删除</button>':''}</div>`:'';if(n){$('#applyUI').onclick=()=>command('ui-patch',{ui_node_id:n.ui_node_id,patch:{name:$('#uiName').value,text:$('#uiText').value,offsets:{...(n.offsets||{}),left:Number($('#uiLeft').value),top:Number($('#uiTop').value)}}});if($('#deleteUI'))$('#deleteUI').onclick=()=>command('ui-remove',{ui_node_id:n.ui_node_id})}return}if(leftTab==='input'){const p=activeInputProfile();$('#inspectTitle').textContent=p?.name||'输入';$('#inspectSub').textContent=p?.profile_id||'—';$('#selectionKind').textContent='input-profile';$('#inspector').innerHTML=`<div class="field"><label>动作数量</label><input value="${Object.keys(p?.actions||{}).length}" disabled></div><div class="field"><label>运行时重绑定</label><input id="rebindKey" value="KeyK"></div><div class="inspect-actions"><button id="rebindAttack" class="primary">将攻击追加到该键</button></div>`;$('#rebindAttack').onclick=()=>command('input-rebind',{action:'attack',binding:{device:'keyboard',code:$('#rebindKey').value}});return}if(leftTab==='tilemap'){const t=activeTilemap();$('#inspectTitle').textContent=t?.name||'TileMap';$('#inspectSub').textContent=t?.tilemap_id||'—';$('#selectionKind').textContent='tilemap';$('#inspector').innerHTML=t?`<div class="field-row"><div class="field"><label>宽度</label><input value="${t.width}" disabled></div><div class="field"><label>高度</label><input value="${t.height}" disabled></div></div><div class="field-row"><div class="field"><label>单元格</label><input value="${t.cell_size}px" disabled></div><div class="field"><label>当前瓦片</label><input value="${selectedTileId} · ${esc(tileDef(selectedTileId).name)}" disabled></div></div><div class="field"><label>TileMap Root</label><input value="${esc(t.tilemap_root||'offline')}" disabled></div><div class="field"><label>当前图层</label><input value="${esc(selectedLayerId)}" disabled></div>`:'';return}const n=currentScene().nodes.find(n=>n.node_id===selectedNodeId);if(!n){$('#inspectTitle').textContent='未选择节点';$('#inspectSub').textContent='选择节点或地图进行编辑';$('#selectionKind').textContent='—';$('#inspector').innerHTML='';return}const a=project.assets.registry[n.asset_id];$('#inspectTitle').textContent=n.name;$('#inspectSub').textContent=n.node_id;$('#selectionKind').textContent=n.components?.navigation_agent?'navigation-agent':a?.kind||'node';$('#inspector').innerHTML=`<div class="field"><label>名称</label><input id="fName" value="${esc(n.name)}"></div><div class="field-row"><div class="field"><label>X</label><input id="fX" type="number" value="${Math.round(n.transform.x)}"></div><div class="field"><label>Y</label><input id="fY" type="number" value="${Math.round(n.transform.y)}"></div></div><div class="field-row"><div class="field"><label>旋转（度）</label><input id="fRot" type="number" value="${(n.transform.rotation_mdeg||0)/1000}"></div><div class="field"><label>层级</label><input id="fZ" type="number" value="${n.z_index||0}"></div></div><div class="field"><label>资产身份</label><input value="${esc(n.asset_id||'无')}" disabled></div><div class="field"><label>导航</label><input value="${n.components?.navigation_agent?'Agent · '+(inspection?.navigation?.positions?.[n.node_id]?.status||'idle'):'非Agent'}" disabled></div><div class="inspect-actions"><button id="applyNode" class="primary">应用修改</button><button id="deleteNode">删除</button></div>`;$('#applyNode').onclick=()=>command('patch-node',{node_id:n.node_id,patch:{name:$('#fName').value,z_index:Number($('#fZ').value),transform:{x:Number($('#fX').value),y:Number($('#fY').value),rotation_mdeg:Math.round(Number($('#fRot').value)*1000)}}});$('#deleteNode').onclick=()=>command('remove-node',{node_id:n.node_id})}
function renderWatch(){const r=inspection?.behavior?.runtime||offlineBehavior||{},p=r.entities?.player?.variables||{},e=r.entities?.enemy?.variables||{};$('#watch').innerHTML=`<div><span>player.health</span><b>${Math.round(p.health??100)}</b></div><div><span>enemy.health</span><b>${Math.round(e.health??75)}</b></div><div><span>globals.score</span><b>${r.globals?.score??0}</b></div><div><span>Tick</span><b>${r.tick??0}</b></div><div><span>State Root</span><b>${esc(String(r.state_root||'offline').slice(0,12))}</b></div>`}
