function uiData(){const r=inspection?.behavior?.runtime||offlineBehavior||{};return{project:{title:project.identity.title},globals:r.globals||{},entities:Object.fromEntries(Object.entries(r.entities||{}).map(([k,v])=>[k,v.variables||{}])),device:{touch:uiDevice==='mobile',kind:uiDevice}}}
function pathValue(o,p){return String(p||'').split('.').filter(Boolean).reduce((v,k)=>v?.[k],o)}
function frontendUILayout(){const t=activeUITree();if(!t)return{nodes:[],focus_order:[],layout_root:'—'};const data=uiData(),by=new Map(t.nodes.map(n=>[n.ui_node_id,clone(n)])),nodes=[];const bind=n=>{const b=n.bindings||{};if(b.visible){const v=pathValue(data,b.visible);if(v!==undefined)n.visible=!!v}if(b.text){const v=pathValue(data,b.text);if(v!==undefined)n.text=String(v)}if(b.value){const v=pathValue(data,b.value);if(v!==undefined)n.value=Number(v)}if(b.text_template)n.text=b.text_template.replace(/\{([^}]+)\}/g,(_,x)=>String(pathValue(data,x)??''));return n};for(const [k,n] of by)by.set(k,bind(n));const size=uiDevice==='mobile'?{w:360,h:640}:{w:640,h:360};const walk=(id,parent,depth=0)=>{const n=by.get(id);if(!n)return;const a=n.anchors||{},o=n.offsets||{},x=parent.x+parent.w*(a.left||0)/1000+(o.left||0),y=parent.y+parent.h*(a.top||0)/1000+(o.top||0),x2=parent.x+parent.w*(a.right||0)/1000+(o.right||0),y2=parent.y+parent.h*(a.bottom||0)/1000+(o.bottom||0),r={x:Math.round(x),y:Math.round(y),width:Math.max(0,Math.round(x2-x||(n.min_size?.width||0))),height:Math.max(0,Math.round(y2-y||(n.min_size?.height||0)))};nodes.push({...n,rect:r,depth});if(n.visible===false)return;for(const c of n.children||[])walk(c,r,depth+1)};walk(t.root_id,{x:0,y:0,w:size.w,h:size.h});const visible=nodes.filter(n=>n.visible!==false);return{nodes:visible,focus_order:visible.filter(n=>n.focus_mode!=='none').sort((a,b)=>(a.navigation?.order||9999)-(b.navigation?.order||9999)).map(n=>n.ui_node_id),layout_root:inspection?.ui?.layout?.layout_root||t.ui_root,size}}
function renderUIPanel(){const t=activeUITree();if(!t){$('#uiPanel').innerHTML='<div class="empty">没有UI树</div>';return}$('#uiPanel').innerHTML=`<div class="map-summary"><b>${esc(t.name)}</b><span>${t.nodes.length} 控件 · ${esc(t.scale_mode)}</span><small>${esc(String(t.ui_root).slice(0,16))}</small></div><h4>控件树</h4>`+t.nodes.map(n=>`<div class="ui-tree-row ${n.ui_node_id===selectedUiNodeId?'selected':''}" data-ui-node="${esc(n.ui_node_id)}" style="padding-left:${8+(n.parent_id?12:0)}px"><span>${n.type==='Label'?'T':n.type==='ProgressBar'?'▰':n.type.includes('Button')?'◉':'□'}</span><b>${esc(n.name)}</b><small>${esc(n.type)}</small></div>`).join('')+`<div class="inspect-actions"><button id="addLabelBtn">+ Label</button><button id="addButtonBtn">+ Button</button></div>`;$$('[data-ui-node]').forEach(el=>el.onclick=()=>{selectedUiNodeId=el.dataset.uiNode;project.editor.selected_ui_node_id=selectedUiNodeId;if(server)command('ui-select',{ui_node_id:selectedUiNodeId});else render()});$('#addLabelBtn').onclick=()=>command('ui-add',{parent_id:'ui:hud',node:{type:'Label',name:'新标签',text:'新标签'}});$('#addButtonBtn').onclick=()=>command('ui-add',{parent_id:'ui:hud',node:{type:'Button',name:'新按钮',text:'按钮',focus_mode:'all',mouse_filter:'stop',events:{pressed:'ui_accept'}}})}
function renderInputPanel(){const p=activeInputProfile(),f=inspection?.input?.last_frame;$('#inputPanel').innerHTML=p?`<div class="map-summary"><b>${esc(p.name)}</b><span>${Object.keys(p.actions).length} 动作 · 键鼠/手柄/触摸</span><small>${esc(String(p.input_root).slice(0,16))}</small></div><h4>动作映射</h4>`+Object.entries(p.actions).map(([name,a])=>{const pressed=f?.actions?.[name]?.pressed,bindings=(a.bindings||[]).map(b=>b.code||('Button '+b.button)||('Axis '+b.axis)||b.node_id).join(' · ');return`<div class="input-action-card"><b>${esc(name)}</b><small>${esc(bindings)}</small><div class="input-meter"><i style="width:${pressed?100:0}%"></i></div></div>`}).join(''):''}
function drawUI(){const l=inspection?.ui?.layout&&uiDevice==='desktop'?inspection.ui.layout:frontendUILayout(),size=l.size||{w:640,h:360};uiCanvas.width=size.w;uiCanvas.height=size.h;uiCtx.clearRect(0,0,size.w,size.h);uiCtx.fillStyle='#071426';uiCtx.fillRect(0,0,size.w,size.h);for(const n of l.nodes){if(n.ui_node_id==='ui:root'||n.type==='Control')continue;const r=n.rect,st=n.style||{};uiCtx.save();uiCtx.globalAlpha=n.enabled===false?.45:1;if(st.background||n.type==='Panel'||n.type.includes('Button')||n.type==='ProgressBar'){uiCtx.fillStyle=st.background||'#10283dcc';uiCtx.beginPath();uiCtx.roundRect(r.x,r.y,r.width,r.height,st.radius||5);uiCtx.fill();if(st.border){uiCtx.strokeStyle=st.border;uiCtx.stroke()}}if(n.type==='ProgressBar'){const v=Math.max(0,Math.min(1,(n.value||0)/(n.max_value||100)));uiCtx.fillStyle=st.fill||'#38bdf8';uiCtx.beginPath();uiCtx.roundRect(r.x,r.y,r.width*v,r.height,st.radius||4);uiCtx.fill()}if(['Label','Button','TouchButton'].includes(n.type)){uiCtx.fillStyle=st.color||'#e0f2fe';uiCtx.font=`${st.font_size||14}px system-ui`;uiCtx.textAlign=st.align==='right'?'right':st.align==='center'?'center':'left';uiCtx.textBaseline='middle';const x=st.align==='right'?r.x+r.width-6:st.align==='center'?r.x+r.width/2:r.x+6;uiCtx.fillText(n.text||n.name,x,r.y+r.height/2)}if(n.ui_node_id===selectedUiNodeId){uiCtx.strokeStyle='#fbbf24';uiCtx.lineWidth=2;uiCtx.setLineDash([5,3]);uiCtx.strokeRect(r.x-2,r.y-2,r.width+4,r.height+4)}if(n.ui_node_id===(inspection?.ui?.focus_id)){uiCtx.strokeStyle='#4ade80';uiCtx.lineWidth=3;uiCtx.strokeRect(r.x-4,r.y-4,r.width+8,r.height+8)}uiCtx.restore()}$('#uiRootBadge').textContent=`UI ${String(l.layout_root||'—').slice(0,10)}`;$('#uiFocusBadge').textContent=`Focus ${inspection?.ui?.focus_id||'—'}`;$('#uiDeviceBadge').textContent=`${uiDevice} ${size.w}×${size.h}`;$('#uiMeta').textContent=`${l.nodes.length} visible · ${l.focus_order?.length||0} focusable`}
function renderUIEditor(){drawUI();const p=activeInputProfile(),f=inspection?.input?.last_frame;$('#inputActions').innerHTML=Object.keys(p?.actions||{}).slice(0,8).map(a=>`<div class="input-action-card"><b>${esc(a)}</b><small>${(p.actions[a].bindings||[]).length} bindings</small><div class="input-meter"><i style="width:${f?.actions?.[a]?.pressed?100:0}%"></i></div></div>`).join('');$('#inputWatch').innerHTML=`<div><span>UI Root</span><b>${esc(String(activeUITree()?.ui_root||'—').slice(0,12))}</b></div><div><span>Input Root</span><b>${esc(String(p?.input_root||'—').slice(0,12))}</b></div><div><span>Focus</span><b>${esc(inspection?.ui?.focus_id||'—')}</b></div><div><span>Device</span><b>${esc(uiDevice)}</b></div>`}

function renderTrace(){const rows=traceCleared?[]:[...(inspection?.event_tail||[]),...(inspection?.behavior?.trace_tail||[])].slice(-80).reverse();$('#trace').innerHTML=rows.map(t=>`<div class="trace-row"><b>${t.tick??t.sequence??'—'}</b><em>${esc(t.type)}</em><span>${esc(JSON.stringify(Object.fromEntries(Object.entries(t).filter(([k])=>!['tick','sequence','type','time'].includes(k)))).slice(0,240))}</span></div>`).join('')||'<div class="empty">运行、绘制地图或查询路径后，因果记录会显示在这里。</div>';$('#traceMeta').textContent=`Tick ${inspection?.behavior?.runtime?.tick??0} · ${rows.length} records`}
function renderBehavior(){const graph=inspection?.behavior?.graphs?.state_machine||{nodes:[],edges:[]},svg=$('#machineGraph');svg.innerHTML=`<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="#3d6c8e"/></marker></defs>`+graph.edges.map(e=>{const a=graph.nodes.find(n=>n.id===e.from),b=graph.nodes.find(n=>n.id===e.to);return a&&b?`<path class="g-edge" marker-end="url(#arrow)" d="M${a.x+130},${a.y+30} C${a.x+170},${a.y+30} ${b.x-40},${b.y+30} ${b.x},${b.y+30}"/>`:''}).join('')+graph.nodes.map(n=>`<g class="g-node ${n.initial?'active':''}" transform="translate(${n.x},${n.y})"><rect width="130" height="60" rx="9"/><text x="12" y="25">${esc(n.label)}</text><text class="sub" x="12" y="44">转移 ${n.transition_count??0}</text></g>`).join('');$('#machineMeta').textContent=`${graph.nodes.length} 状态 · ${graph.edges.length} 转移`;const rules=inspection?.behavior?.graphs?.rules?.nodes?.filter(n=>n.kind==='rule')||[];$('#ruleList').innerHTML=rules.map(r=>`<div class="rule"><b>${esc(r.label)}</b><small>${esc(r.event)} · ${r.actions} 个动作 · 优先级 ${r.priority}</small></div>`).join('');$('#ruleMeta').textContent=`${rules.length} 规则`}
function renderBuild(){const targets=project.build.targets||['web'];$('#buildCards').innerHTML=targets.map(t=>`<div class="build-card"><span>目标平台</span><b>${esc(t)}</b><span>${t==='web'?'可直接导出':'构建目标'}</span></div>`).join('');$('#buildManifest').textContent=JSON.stringify({entry_scene:project.build.entry_scene_id,quality:project.build.quality_profile,assets:project.assets.order.length,nodes:currentScene().nodes.length,tilemaps:currentScene().tilemaps?.length||0,navigation_agents:Object.keys(inspection?.navigation?.positions||{}).length,behavior:project.behavior.active_program_id,outputs:['project.json','scene-player.json','behavior.json','assets.json','tilemap-navigation.manifest.json','gpu-viewport.manifest.json','ui-input.manifest.json','gateway.runtime.json','web-preview.html']},null,2)}
function renderTabs(){$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===activeView));$$('.view').forEach(v=>v.classList.remove('active'));$(`#${activeView}View`)?.classList.add('active');$$('[data-left]').forEach(b=>b.classList.toggle('active',b.dataset.left===leftTab));$('#scenePanel').classList.toggle('hidden',leftTab!=='scene');$('#assetPanel').classList.toggle('hidden',leftTab!=='assets');$('#tilemapPanel').classList.toggle('hidden',leftTab!=='tilemap');$('#uiPanel').classList.toggle('hidden',leftTab!=='ui');$('#inputPanel').classList.toggle('hidden',leftTab!=='input');$$('[data-tool]').forEach(b=>b.classList.toggle('on',b.dataset.tool===tool));$('#toolBadge').textContent=toolNames[tool]||tool;$('#leftHint').textContent=leftTab==='tilemap'?'选择瓦片后在画布绘制':leftTab==='assets'?'拖拽资产到画布':leftTab==='ui'?'选择控件并编辑锚点':leftTab==='input'?'查看和重绑定动作':'选择节点并拖动'}
