function setTool(next){tool=next;project.editor.active_tool=next;if(next.startsWith('tile'))leftTab='tilemap';if(next==='select')leftTab='scene';renderTabs();renderInspector();drawAll()}
function canvasPoint(e,target=canvas){const r=target.getBoundingClientRect();return{x:(e.clientX-r.left)*target.width/r.width,y:(e.clientY-r.top)*target.height/r.height}}
function cellPoint(p){const t=activeTilemap();return{x:Math.floor((p.x-t.origin.x)/t.cell_size),y:Math.floor((p.y-t.origin.y)/t.cell_size)}}
function hitNode(px,py){const nodes=[...(inspection?.scene?.projection?.nodes||currentScene().nodes)].sort((a,b)=>b.z_index-a.z_index);return nodes.find(n=>Math.abs(px-n.transform.x)<34&&py-n.transform.y<70&&py>n.transform.y-80)}
async function commitPaint(){if(!paintCells.size)return;const cells=[...paintCells.values()];paintCells.clear();await command('tile-edit',{operation:'cells',layer_id:selectedLayerId,tile_id:tool==='tile-erase'?0:selectedTileId,cells})}
async function handlePathPoint(p){if(!navStart){navStart=p;toast('已设置路径起点，请点击终点');drawAll();return}try{if(server){const result=await api('/api/unified/session/command',{session_id:sessionId,command:'navigation-query',start:navStart,end:p,smooth:true,exclude_node_ids:['node:navigation-scout']});navPath=result.path;inspection=await api('/api/unified/session/inspect',{session_id:sessionId});syncProjectFromSession()}else navPath=offlinePath(navStart,p);toast(navPath.status==='ok'?`路径完成：${navPath.world_points.length} 个拐点`:'目标不可达')}catch(e){toast(e.message)}finally{navStart=null;render()}}
function gridWalkable(t,x,y){if(x<0||y<0||x>=t.width||y>=t.height)return false;const l=t.layers.find(l=>l.kind==='navigation')||t.layers.find(l=>l.layer_id==='layer:terrain'),id=l.cells[y*t.width+x],d=t.tileset.tiles[String(id)]||t.tileset.tiles['0'];return d.walkable!==false&&!d.solid}
function offlinePath(a,b){const t=activeTilemap(),s=cellPoint(a),g=cellPoint(b),q=[s],came=new Map(),seen=new Set([`${s.x},${s.y}`]);while(q.length){const c=q.shift();if(c.x===g.x&&c.y===g.y)break;for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const n={x:c.x+dx,y:c.y+dy},k=`${n.x},${n.y}`;if(!seen.has(k)&&gridWalkable(t,n.x,n.y)){seen.add(k);came.set(k,`${c.x},${c.y}`);q.push(n)}}}let k=`${g.x},${g.y}`;if(!seen.has(k))return{status:'unreachable',world_points:[],cells:[],path_root:'offline-unreachable'};const cells=[];while(k){const [x,y]=k.split(',').map(Number);cells.push({x,y});if(k===`${s.x},${s.y}`)break;k=came.get(k)}cells.reverse();const points=cells.filter((_,i)=>i===0||i===cells.length-1||i%8===0).map(c=>({x:t.origin.x+c.x*t.cell_size+t.cell_size/2,y:t.origin.y+c.y*t.cell_size+t.cell_size/2}));return{status:'ok',cells,world_points:points,visited:seen.size,cost:cells.length*10,path_root:`offline-${cells.length}-${seen.size}`}}
canvas.onpointerdown=e=>{const p=canvasPoint(e);if(tool==='select'){const n=hitNode(p.x,p.y);if(n){selectedNodeId=n.node_id;dragNode=n.node_id;dragOffset={x:p.x-n.transform.x,y:p.y-n.transform.y};canvas.setPointerCapture(e.pointerId);command('select',{node_id:n.node_id})}}else if(tool==='navigation-path')handlePathPoint(p);else{const c=cellPoint(p);if(tool==='tile-fill'){command('tile-edit',{operation:'fill',layer_id:selectedLayerId,tile_id:selectedTileId,x:c.x,y:c.y});return}painting=true;paintCells.set(`${c.x},${c.y}`,c);canvas.setPointerCapture(e.pointerId);drawAll()}}
canvas.onpointermove=e=>{const p=canvasPoint(e);if(dragNode){const n=currentScene().nodes.find(x=>x.node_id===dragNode);if(n){n.transform.x=p.x-dragOffset.x;n.transform.y=p.y-dragOffset.y;drawAll()}}else if(painting){const c=cellPoint(p);paintCells.set(`${c.x},${c.y}`,c);drawAll()}}
canvas.onpointerup=e=>{if(dragNode){const p=canvasPoint(e),id=dragNode;dragNode=null;command('move-node',{node_id:id,x:p.x-dragOffset.x,y:p.y-dragOffset.y,snap:project.editor.snap_to_grid})}else if(painting){painting=false;commitPaint()}}
canvas.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='copy'};canvas.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/asset-id');if(!id)return;const p=canvasPoint(e);command('add-asset-node',{asset_id:id,x:p.x,y:p.y,bind_entity:true});toast('资产已进入场景并绑定行为实体')}
navCanvas.onclick=e=>{setTool('navigation-path');handlePathPoint(canvasPoint(e,navCanvas))}
async function routeScout(){const target={x:568,y:280};await command('navigation-target',{node_id:'node:navigation-scout',x:target.x,y:target.y,speed_milli:3200});const start=inspection?.navigation?.positions?.['node:navigation-scout']||{x:88,y:72};if(server){const r=await api('/api/unified/session/command',{session_id:sessionId,command:'navigation-query',start,end:target,smooth:true,exclude_node_ids:['node:navigation-scout']});navPath=r.path;inspection=await api('/api/unified/session/inspect',{session_id:sessionId});syncProjectFromSession()}else navPath=offlinePath(start,target);render()}
function inputState(){const gp=[...(navigator.getGamepads?.()||[])].filter(Boolean).map(g=>({axes:[...g.axes],buttons:g.buttons.map(b=>({pressed:b.pressed,value:b.value}))}));return{raw:{keys:Object.keys(keys).filter(k=>keys[k]),gamepads:gp,touches:[]}}}
async function startRun(){if(running)return;running=true;render();runTimer=setInterval(async()=>{if(stepping)return;stepping=true;try{if(server){inspection=await api('/api/unified/session/command',{session_id:sessionId,command:'step',input:inputState()});syncProjectFromSession()}else localCommand('step',{input:inputState()});render()}finally{stepping=false}},50)}
function stopRun(){running=false;if(runTimer){clearInterval(runTimer);runTimer=null}render()}
async function exportRuntime(){try{const out=server?await api('/api/unified/session/export',{session_id:sessionId}):{project,scene_player:localInspect().scene.projection,behavior_program:project.behavior.programs[project.behavior.active_program_id],tilemap_navigation:{tilemap:activeTilemap(),path:navPath},gpu:{preferred_backend:'webgpu',fallback:'canvas2d'}};download('Reality_Studio_v1.4_三维具身统一运行包.json',out);toast('UI输入统一运行包已导出')}catch(e){toast(e.message)}}
async function detect(){try{const h=await api('/api/health');server=true;$('#serverDot').className='dot ok';$('#serverText').textContent=`原生服务 · v${h.studio_version}`;project=await api('/api/unified/sample')}catch{server=false;$('#serverDot').className='dot warn';$('#serverText').textContent='离线统一制造';project=clone(window.SAMPLE_UNIFIED)}await createSession()}
window.RealityStudioApp={getProject:()=>project,getInspection:()=>inspection,isServer:()=>server,command,refresh:()=>render(),setView:(view,left=view)=>{activeView=view;leftTab=left;render()},setProject:(next)=>{project=clone(next);return createSession()},toast};
$$('[data-view]').forEach(b=>b.onclick=()=>{activeView=b.dataset.view;render()});$$('[data-left]').forEach(b=>b.onclick=()=>{leftTab=b.dataset.left;if(leftTab==='tilemap'&&!tool.startsWith('tile'))setTool('tile-paint');else{if(leftTab==='ui'||leftTab==='input')activeView='ui';render()}});$$('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));
$('#playBtn').onclick=startRun;$('#pauseBtn').onclick=stopRun;$('#stepBtn').onclick=()=>command('step',{input:inputState()});$('#resetBtn').onclick=()=>{stopRun();navPath=null;command('reset')};$('#undoBtn').onclick=()=>command('undo');$('#redoBtn').onclick=()=>command('redo');$('#gpuBtn').onclick=()=>{gpuEnabled=!gpuEnabled;$('#gpuBtn').classList.toggle('on',gpuEnabled);gpuViewport.setEnabled(gpuEnabled);scheduleGPU(true)};$('#qualitySelect').value=gpuQuality;$('#qualitySelect').onchange=async e=>{gpuQuality=e.target.value;if(server)await command('gpu-options',{quality:gpuQuality});scheduleGPU(true)};$('#snapBtn').onclick=()=>{project.editor.snap_to_grid=!project.editor.snap_to_grid;$('#snapBtn').classList.toggle('on',project.editor.snap_to_grid);drawAll()};$('#gridBtn').onclick=()=>{project.editor.snap_to_grid=!project.editor.snap_to_grid;$('#gridBtn').classList.toggle('on',project.editor.snap_to_grid);drawAll()};$('#validateBtn').onclick=async()=>{const v=server?await api('/api/unified/validate',{project}):{valid:true,errors:[]};toast(v.valid?'统一项目与TileMap校验通过':`${v.errors.length} 项错误`)};$('#exportBtn').onclick=exportRuntime;$('#saveBtn').onclick=()=>download(`${project.identity.title}.unified-project.json`,project);$('#openBtn').onclick=()=>$('#fileInput').click();$('#importAssetBtn').onclick=()=>$('#assetFileInput').click();$('#assetFileInput').onchange=async e=>{const files=[...e.target.files];for(const file of files){try{const payload=await filePayload(file);await command('import-embedded-asset',{file:payload})}catch(x){toast(`${file.name}: ${x.message}`)}}if(files.length)toast(`已导入 ${files.length} 个资产`);e.target.value=''};$('#fileInput').onchange=async e=>{try{project=JSON.parse(await e.target.files[0].text());await createSession();toast('项目已打开')}catch(x){toast(x.message)}e.target.value=''};$('#newBtn').onclick=()=>{project=clone(window.SAMPLE_UNIFIED);project.identity.title='新TileMap世界';createSession()};$('#clearTraceBtn').onclick=()=>{traceCleared=true;renderTrace()};$('#routeScoutBtn').onclick=routeScout;$('#clearRouteBtn').onclick=()=>{navPath=null;navStart=null;command('navigation-clear',{node_id:'node:navigation-scout'});render()};
$$('[data-device]').forEach(b=>b.onclick=()=>{uiDevice=b.dataset.device;project.editor.ui_preview_device=uiDevice;$$('[data-device]').forEach(x=>x.classList.toggle('active',x.dataset.device===uiDevice));renderUIEditor()});$('#focusLeftBtn').onclick=()=>command('ui-focus',{direction:'left'});$('#focusRightBtn').onclick=()=>command('ui-focus',{direction:'right'});$('#testAttackBtn').onclick=()=>command('step',{input:{raw:{keys:['Space']}}});uiCanvas.onclick=e=>{const p=canvasPoint(e,uiCanvas),layout=inspection?.ui?.layout&&uiDevice==='desktop'?inspection.ui.layout:frontendUILayout(),n=[...layout.nodes].reverse().find(n=>p.x>=n.rect.x&&p.y>=n.rect.y&&p.x<=n.rect.x+n.rect.width&&p.y<=n.rect.y+n.rect.height);if(n){selectedUiNodeId=n.ui_node_id;leftTab='ui';if(running&&server)command('ui-event',{type:'pressed',x:p.x,y:p.y,touch:uiDevice==='mobile'});else command('ui-select',{ui_node_id:n.ui_node_id})}};
const keys={};window.addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault()});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('beforeunload',()=>{stopRun();gpuViewport.destroy()});
detect().catch(e=>{document.body.innerHTML=`<pre style="padding:30px;color:#fecaca">Reality Studio v1.5 启动失败\n${esc(e.stack||e.message)}</pre>`});
